{
  "ok": true,
  "category": "batch",
  "operations": [
    {
      "name": "batch.run",
      "description": "Execute multiple operations in a single IPC call (~400ms total instead of 400ms × N). Operations run sequentially inside ONE undo group — a single Ctrl+Z reverts the whole batch, however many ops it contained. That group is also why undo/redo children (project.undo, command.execute id 16/2035) are rejected here: call those as their own ae_do. If one fails, subsequent ops still run unless stopOnError. Results array matches input order; the response reports how many failed. Mix in read/verify children — comp.info, layer.info, render.frame — to mutate AND verify in the same call, e.g. [...mutations, { operation: 'render.frame', args: { … } }].",
      "readOnly": true,
      "params": [
        {
          "name": "ops",
          "type": "array",
          "required": true,
          "description": "Array of { operation, args } objects, e.g. [{ \"operation\": \"layer.create_solid\", \"args\": { \"comp\": \"Main\", \"color\": [1,0,0] } }]"
        },
        {
          "name": "stopOnError",
          "type": "boolean",
          "required": false,
          "description": "Stop executing remaining ops if one fails (default false)"
        }
      ]
    }
  ]
}

